package com.tdi.ubldetect.catalog

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** Which pipeline the viewer is running. */
enum class Mode { QPDS, POSM }

/**
 * One slab or one POSM category: what to expect and what to call it.
 *
 * Generated by tools/gen_catalog.py, which resolves class names to the
 * exported model's indices while both are in hand. The app never maps a name
 * to an index, so it cannot disagree with the model about what class 12 is.
 */
@Serializable
data class CatalogEntry(
    val key: String,
    val subtitle: String,
    @SerialName("class_ids") private val classIdList: List<Int> = emptyList(),
    val display: Map<String, String> = emptyMap(),
    @SerialName("missing_from_model") val missingFromModel: List<String> = emptyList(),
    @SerialName("unmapped_model_classes") val unmappedModelClasses: List<String> = emptyList(),
) {
    /** Membership set, because filtering happens per detection per frame. */
    val classIds: Set<Int> get() = classIdList.toSet()

    /**
     * True when nothing here can ever be labelled.
     *
     * Not a theoretical state: `mini_meals` is in exactly this condition in
     * the live catalog, because the deployed model has no class for its one
     * material. Starting a camera on it would show an empty screen that looks
     * like a broken detector, so the picker says so instead.
     */
    val isEmpty: Boolean get() = classIdList.isEmpty()
}

@Serializable
private data class CatalogDto(
    @SerialName("qpds_slabs") val qpdsSlabs: List<CatalogEntry> = emptyList(),
    @SerialName("posm_categories") val posmCategories: List<CatalogEntry> = emptyList(),
)

class Catalog(
    val qpdsSlabs: List<CatalogEntry>,
    val posmCategories: List<CatalogEntry>,
) {
    fun entries(mode: Mode): List<CatalogEntry> = when (mode) {
        Mode.QPDS -> qpdsSlabs
        Mode.POSM -> posmCategories
    }

    /**
     * Label for a detected class within one entry.
     *
     * Falls back to the raw index rather than hiding the detection: with the
     * allowlist toggled off the app deliberately draws classes the chosen
     * entry never expected, and "class 41" is more useful than a blank.
     */
    fun labelFor(entry: CatalogEntry, classId: Int): String =
        entry.display[classId.toString()] ?: "class $classId"

    companion object {
        private val json = Json { ignoreUnknownKeys = true }

        fun parse(text: String): Catalog {
            val dto = json.decodeFromString(CatalogDto.serializer(), text)
            return Catalog(dto.qpdsSlabs, dto.posmCategories)
        }
    }
}
